const items = $input.all();

// Buscar la fila donde ok es verdadero y tiene id válido
const exito = items.find(item => {
  const r = item.json || {};
  return (r.ok === true || r.ok === 'true') && r.id !== null && r.id !== undefined;
});

if (exito) {
  const r = exito.json;
  return [{ json: { ok: true, usuario_id: r.id, nombre: r.nombre, email: r.email, mensaje: 'Usuario registrado correctamente' } }];
}

return [{ json: { ok: false, mensaje: 'El email ya está registrado. Prueba iniciando sesión.' } }];

